export type JsonValue = unknown;

/**
 * Meeting
 */
export type Meeting = {
    /**
     * Id
     */
    id: string;
    /**
     * Course Id
     */
    course_id: string;
    /**
     * Term Id
     */
    term_id: string;
    /**
     * Section Code
     */
    section_code: string;
    /**
     * Type Code
     */
    type_code: string;
    /**
     * Title
     */
    title: string | null;
    /**
     * Instructor
     */
    instructor: string | null;
    /**
     * Location
     */
    location: string | null;
    /**
     * Weekday
     *
     * 1 = Monday .. 7 = Sunday
     */
    weekday: number;
    /**
     * Start Time
     *
     * Wall-clock time in the Program's time zone
     */
    start_time: string;
    /**
     * End Time
     */
    end_time: string;
    /**
     * Recurrence
     */
    recurrence: 'weekly' | 'biweekly';
    /**
     * Anchor Week
     *
     * Biweekly: the term week it starts alternating from
     */
    anchor_week: number;
    /**
     * Start Week
     */
    start_week: number;
    /**
     * End Week
     *
     * Last term week; null = until the end of term
     */
    end_week: number | null;
    /**
     * Skip Breaks
     */
    skip_breaks: boolean;
    /**
     * Enabled
     */
    enabled: boolean;
    /**
     * Source Kind
     */
    source_kind: string | null;
    /**
     * Source Ref
     */
    source_ref: string | null;
    /**
     * Exceptions
     *
     * Cancelled or moved dates
     */
    exceptions: Array<MeetingException>;
    /**
     * Created At
     */
    created_at: string;
    /**
     * Updated At
     */
    updated_at: string;
};

/**
 * MeetingCreateInputBody
 */
export type MeetingCreateInputBody = {
    /**
     * Term Id
     *
     * Term of the course the meeting runs in
     */
    term_id: string;
    /**
     * Section Code
     *
     * Section, e.g. 'LEC0101'
     */
    section_code?: string;
    /**
     * Type Code
     *
     * Event type code of the Program, e.g. 'LEC'
     */
    type_code: string;
    /**
     * Title
     *
     * Optional title
     */
    title?: string | null;
    /**
     * Instructor
     *
     * Instructor
     */
    instructor?: string | null;
    /**
     * Location
     *
     * Room or building
     */
    location?: string | null;
    /**
     * Weekday
     *
     * 1 = Monday .. 7 = Sunday
     */
    weekday: number;
    /**
     * Start Time
     *
     * Start, wall-clock time in the Program's time zone
     */
    start_time: string;
    /**
     * End Time
     *
     * End, after the start
     */
    end_time: string;
    /**
     * Recurrence
     *
     * Every week or every other week
     */
    recurrence?: 'weekly' | 'biweekly';
    /**
     * Anchor Week
     *
     * Biweekly: first week it happens; defaults to start_week
     */
    anchor_week?: number | null;
    /**
     * Start Week
     *
     * First term week
     */
    start_week?: number;
    /**
     * End Week
     *
     * Last term week; null = until the end of term
     */
    end_week?: number | null;
    /**
     * Skip Breaks
     *
     * No class in break weeks and on breaks
     */
    skip_breaks?: boolean;
    /**
     * Enabled
     *
     * Disabled sections are not shown
     */
    enabled?: boolean;
    /**
     * Source Kind
     *
     * Importer that created it, e.g. 'ics'
     */
    source_kind?: string | null;
    /**
     * Source Ref
     *
     * Id of the item in the import source, for de-duplication
     */
    source_ref?: string | null;
};

